  --font-mono: var(--font-jetbrains-mono), ui-monospace, "SF Mono", monospace;
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-card: 10px;
  --radius-window: 14px;
}

html:root {
  --color-background-full: oklch(0.985 0.001 286.376);
  --color-background-primary-default: oklch(1 0 0);
  --color-background-secondary-default: oklch(0.961 0.002 247.84);
  --color-background-primary-hover: oklch(0.97 0.002 247.839);
  --color-text-primary: oklch(0.247 0.006 258.361);
  --color-text-secondary: oklch(0.506 0.01 264.477);
  --color-text-tertiary: oklch(0.54 0.01 264.484);
  --color-border-button-default: oklch(0.912 0.005 258.326);
  --color-separator-border: oklch(0.946 0.003 264.542);
  --font-mono-source: var(--font-jetbrains-mono);
}

html.dark {
  --color-background-full: oklch(0.209 0.004 264.477);
  --color-background-primary-default: oklch(0.26 0.006 271.191);
  --color-background-secondary-default: oklch(0.231 0.004 264.487);
  --color-background-primary-hover: oklch(0.289 0.006 271.22);
  --color-text-primary: oklch(0.964 0.002 247.839);
  --color-text-secondary: oklch(0.731 0.008 260.731);
  --color-text-tertiary: oklch(0.7 0.008 260.731);
  --color-border-button-default: oklch(0.356 0.007 264.474);
  --color-separator-border: oklch(0.308 0.006 258.354);
}

html:root,
html.dark {
  --color-border-focus-ring: var(--color-text-primary);
  --color-tab-count-selected-background: var(--color-background-secondary-default);
  --background: var(--color-background-full);
  --foreground: var(--color-text-primary);
  --card: var(--color-background-primary-default);
  --card-foreground: var(--color-text-primary);
  --popover: var(--color-background-primary-default);
  --popover-foreground: var(--color-text-primary);
  --primary: var(--color-text-primary);
  --primary-foreground: var(--color-background-primary-default);
  --secondary: var(--color-background-secondary-default);
  --secondary-foreground: var(--color-text-primary);
  --muted: var(--color-background-secondary-default);
  --muted-foreground: var(--color-text-secondary);
  --accent: var(--color-background-primary-hover);
  --accent-foreground: var(--color-text-primary);
  --border: var(--color-separator-border);
  --input: var(--color-border-button-default);
  --sidebar: var(--color-background-full);
  --sidebar-foreground: var(--color-text-primary);
  --sidebar-accent: var(--color-background-secondary-default);
  --sidebar-border: var(--color-separator-border);
